// Hilfsfunktion: Wandelt das SVG in ein PNG-Bild (Base64) um für den PDF Export
export const getLogoAsBase64 = async (): Promise<string> => {
    return new Promise((resolve, reject) => {
        try {
            const img = new Image();
            // Erstelle einen Blob aus dem SVG String
            const svgBlob = new Blob([LOGO_SVG_XML], { type: 'image/svg+xml;charset=utf-8' });
            const url = URL.createObjectURL(svgBlob);

            img.onload = () => {
                const canvas = document.createElement('canvas');
                // Hohe Auflösung für scharfen Druck
                canvas.width = 1200;
                canvas.height = 320;
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    URL.revokeObjectURL(url);
                    return reject(new Error("Canvas context failed"));
                }
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                const dataUrl = canvas.toDataURL('image/png');
                URL.revokeObjectURL(url);
                resolve(dataUrl);
            };

            img.onerror = (e) => {
                URL.revokeObjectURL(url);
                reject(new Error("Image load failed"));
            };

            img.src = url;
        } catch (e) {
            reject(e);
        }
    });
};

