            </div>

            <div className="pt-6 border-t border-gray-100">
                <Button 
                    type="submit" 
                    className="w-full py-4 text-lg font-bold shadow-lg transform active:scale-95 transition-transform" 
                    variant="primary"
                >
                    Bericht abschließen & Hochladen
                </Button>
            </div>

            </form>
        </div>
      )}
    </div>
  );
}

