</svg>
`;

interface LogoProps {
  className?: string;
  customSvg?: string | null;
}

export const Logo: React.FC<LogoProps> = ({ className = "h-16", customSvg }) => {
  // Wenn ein Custom SVG übergeben wurde, nutzen wir das, sonst den Standard
  const svgContent = customSvg || DEFAULT_LOGO_XML;

  // Wir stellen sicher, dass das SVG style-Attribute für responsive Darstellung hat,
  // falls der Nutzer ein SVG ohne Größenangaben hochlädt.
  // Wir injizieren style="width:100%; height:100%;" in den ersten <svg> Tag, wenn es fehlt.
  let finalSvg = svgContent;
  if (!finalSvg.includes('height: 100%') && !finalSvg.includes('height:100%')) {
      finalSvg = finalSvg.replace('<svg', '<svg style="height: 100%; width: auto;" ');
  }

  return (
    <div 
      className={className} 
      dangerouslySetInnerHTML={{ __html: finalSvg }} 
    />
  );
};

// Hilfsfunktion: Wandelt das SVG in ein PNG-Bild (Base64) um für den PDF Export
// Akzeptiert nun optional das customSvg
export const getLogoAsBase64 = async (customSvg?: string | null): Promise<string> => {
    return new Promise((resolve, reject) => {
        try {
            const xml = customSvg || DEFAULT_LOGO_XML;
            const img = new Image();
            // Erstelle einen Blob aus dem SVG String
            const svgBlob = new Blob([xml], { type: 'image/svg+xml;charset=utf-8' });
            const url = URL.createObjectURL(svgBlob);

            img.onload = () => {
                // Dynamische Berechnung der Canvas-Größe basierend auf dem Bild-Aspekt
                // Wir setzen eine hohe Zielbreite für gute Druckqualität (ca 1200px)
                const targetWidth = 1200;
                let targetHeight = 320; // Fallback

                // Wenn das Bild Dimensionen hat, berechnen wir die Höhe proportional
                if (img.width > 0 && img.height > 0) {
                    targetHeight = (img.height / img.width) * targetWidth;
                }

                const canvas = document.createElement('canvas');
                canvas.width = targetWidth;
                canvas.height = targetHeight;

                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    URL.revokeObjectURL(url);
                    return reject(new Error("Canvas context failed"));
                }

                // Zeichnen des Bildes auf den Canvas
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

                const dataUrl = canvas.toDataURL('image/png');
                URL.revokeObjectURL(url);
                resolve(dataUrl);
            };

            img.onerror = (e) => {
                URL.revokeObjectURL(url);
                reject(new Error("Image load failed"));
            };

            img.src = url;
        } catch (e) {
            reject(e);
        }
    });
};

