        <div className="max-w-3xl mx-auto p-4 md:p-6 lg:p-8">

            {status.message && (
            <div className="mb-6 bg-red-50 border-l-4 border-red-500 text-red-700 px-4 py-3 rounded shadow-sm">
                <strong className="font-bold">Achtung: </strong>
