                                <InfoIcon /> Einrichtungshilfe (IONOS)
                             </button>
                        </div>

                        {showHelp && (
                            <div className="mb-4 bg-blue-50 p-3 rounded-lg text-[10px] leading-relaxed text-blue-900 border border-blue-200">
                                <p className="font-bold mb-1">IONOS Nextcloud .htaccess Fix:</p>
                                <p className="mb-2 italic">Pfad: /deine_nextcloud/.htaccess</p>
                                <pre className="bg-white p-2 rounded border text-[9px] mb-2 overflow-x-auto select-all">
{`<IfModule mod_headers.c>
  SetEnvIf Origin "${currentAppDomain}" APP_ORIGIN=$0
  Header set Access-Control-Allow-Origin %{APP_ORIGIN}e env=APP_ORIGIN
  Header set Access-Control-Allow-Methods "GET, POST, OPTIONS, PUT, MKCOL"
