                            <input placeholder="Vollständiger Name" value={newTechName} onChange={e => setNewTechName(e.target.value)} className="w-full p-2 border rounded text-sm" />
                            <div className="grid grid-cols-2 gap-2">
                                <input placeholder="Kürzel (Login)" value={newTechCode} onChange={e => setNewTechCode(e.target.value)} className="w-full p-2 border rounded text-sm" />
