                </div>

                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-3">Fotos ({entry.images.length})</label>
                    <div className="grid grid-cols-4 sm:grid-cols-6 gap-3">
                        {entry.images.map((f, i) => (
                            <div key={i} className="relative aspect-square border rounded overflow-hidden group">
                                <img src={URL.createObjectURL(f)} className="w-full h-full object-cover" />
                                <button type="button" onClick={() => setEntry({...entry, images: entry.images.filter((_, idx) => idx !== i)})} className="absolute top-0 right-0 bg-red-500 text-white p-0.5 rounded-bl opacity-0 group-hover:opacity-100"><TrashIcon /></button>
                            </div>
                        ))}
                        <label className="aspect-square flex flex-col items-center justify-center border-2 border-dashed border-gray-300 rounded cursor-pointer hover:bg-gray-50">
                            <CameraIcon />
                            <input type="file" accept="image/*" capture="environment" multiple onChange={e => e.target.files && setEntry({...entry, images: [...entry.images, ...Array.from(e.target.files)]})} className="hidden" />
                        </label>
                    </div>
                </div>

                <div className="pt-6 border-t">
                    <Button type="submit" className="w-full py-4 text-xl font-bold shadow-xl">Absenden</Button>
                </div>
            </form>
        </div>
      )}

      {showSettings && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
            <div className="bg-white rounded-xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-6 border-b pb-4">
                    <h3 className="text-xl font-bold text-brand-900">Verwaltung</h3>
                    <button onClick={() => setShowSettings(false)} className="p-1 text-gray-500 hover:text-gray-800 transition-colors"><CloseIcon /></button>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                    {/* Projekte Verwaltung */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                             <h4 className="text-sm font-bold uppercase text-brand-600">Projekte</h4>
                             <button onClick={() => setShowHelp(!showHelp)} className="text-brand-500 hover:text-brand-700 flex items-center gap-1 text-[10px] font-bold bg-brand-50 px-2 py-1 rounded">
                                <InfoIcon /> Einrichtungshilfe (IONOS)
                             </button>
                        </div>

                        {showHelp && (
                            <div className="mb-4 bg-blue-50 p-3 rounded-lg text-[10px] leading-relaxed text-blue-900 border border-blue-200">
                                <p className="font-bold mb-1">IONOS Nextcloud .htaccess Fix:</p>
                                <p className="mb-2 italic">Pfad: /deine_nextcloud/.htaccess</p>
                                <pre className="bg-white p-2 rounded border text-[9px] mb-2 overflow-x-auto select-all">
{`<IfModule mod_headers.c>
  SetEnvIf Origin "${currentAppDomain}" APP_ORIGIN=$0
  Header set Access-Control-Allow-Origin %{APP_ORIGIN}e env=APP_ORIGIN
  Header set Access-Control-Allow-Methods "GET, POST, OPTIONS, PUT, MKCOL"
  Header set Access-Control-Allow-Headers "Authorization, Content-Type, Origin"
</IfModule>`}
                                </pre>
                                <button onClick={() => copyToClipboard(`<IfModule mod_headers.c>\n  SetEnvIf Origin "${currentAppDomain}" APP_ORIGIN=$0\n  Header set Access-Control-Allow-Origin %{APP_ORIGIN}e env=APP_ORIGIN\n  Header set Access-Control-Allow-Methods "GET, POST, OPTIONS, PUT, MKCOL"\n  Header set Access-Control-Allow-Headers "Authorization, Content-Type, Origin"\n</IfModule>`)} className="bg-brand-600 text-white px-2 py-1 rounded font-bold">Code kopieren</button>
                            </div>
                        )}

                        <div className="space-y-2 mb-4 max-h-48 overflow-y-auto pr-1 border rounded p-2 bg-gray-50">
                            {config.projects.length === 0 && <p className="text-xs text-gray-400 italic">Keine Projekte angelegt.</p>}
                            {config.projects.map(p => (
                                <div key={p.token} className="flex justify-between items-center p-2 bg-white rounded border text-sm shadow-sm">
                                    <span className="font-medium truncate mr-2">{p.name}</span>
                                    <button onClick={() => saveConfig({...config, projects: config.projects.filter(pr => pr.token !== p.token)})} className="text-red-400 hover:text-red-600"><TrashIcon /></button>
                                </div>
                            ))}
                        </div>
                        <div className="space-y-2 bg-white p-3 rounded border">
                            <input placeholder="Projektname" value={newProjName} onChange={e => setNewProjName(e.target.value)} className="w-full p-2 border rounded text-sm" />
                            <input placeholder="Nextcloud Share-Link" value={newProjLink} onChange={e => setNewProjLink(e.target.value)} className="w-full p-2 border rounded text-sm" />
                            <Button onClick={() => {
                                const token = newProjLink.split('/s/')[1]?.split('/')[0];
                                if (!token || !newProjName) return alert("Pflichtfelder fehlen oder Link ungültig.");
                                saveConfig({...config, projects: [...config.projects, { name: newProjName, link: newProjLink, token }]});
                                setNewProjName(''); setNewProjLink('');
                            }} className="w-full py-2">Hinzufügen</Button>
                        </div>
                    </div>

                    {/* Benutzer Verwaltung */}
                    <div className="space-y-4">
                        <h4 className="text-sm font-bold uppercase text-brand-600">Techniker & Admins</h4>
                        <div className="space-y-2 mb-4 max-h-48 overflow-y-auto pr-1 border rounded p-2 bg-gray-50">
                            {config.technicians.map(t => (
                                <div key={t.id} className="flex justify-between items-center p-2 bg-white rounded border text-sm shadow-sm">
                                    <div className="truncate mr-2">
                                        <span className="font-bold text-brand-700">[{t.code}]</span> {t.name}
                                        {t.role === 'admin' && <span className="ml-1 text-[8px] bg-brand-100 text-brand-800 px-1 rounded align-middle">ADMIN</span>}
                                    </div>
                                    {t.id !== currentUser?.id && (
                                        <button onClick={() => saveConfig({...config, technicians: config.technicians.filter(tech => tech.id !== t.id)})} className="text-red-400 hover:text-red-600"><TrashIcon /></button>
                                    )}
                                </div>
                            ))}
                        </div>
                        <div className="space-y-2 bg-white p-3 rounded border">
                            <input placeholder="Vollständiger Name" value={newTechName} onChange={e => setNewTechName(e.target.value)} className="w-full p-2 border rounded text-sm" />
                            <div className="grid grid-cols-2 gap-2">
                                <input placeholder="Kürzel (Login)" value={newTechCode} onChange={e => setNewTechCode(e.target.value)} className="w-full p-2 border rounded text-sm" />
                                <input type="password" placeholder="Passwort" value={newTechPass} onChange={e => setNewTechPass(e.target.value)} className="w-full p-2 border rounded text-sm" />
                            </div>
                            <select value={newTechRole} onChange={e => setNewTechRole(e.target.value as any)} className="w-full p-2 border rounded text-sm bg-gray-50">
                                <option value="user">Benutzer (Nur Berichte)</option>
                                <option value="admin">Administrator (Einstellungen)</option>
                            </select>
                            <Button onClick={() => {
                                if (!newTechName || !newTechCode) return alert("Name und Kürzel fehlen.");
                                const id = Date.now().toString();
                                saveConfig({...config, technicians: [...config.technicians, { id, name: newTechName, code: newTechCode, password: newTechPass, role: newTechRole }]});
                                setNewTechName(''); setNewTechCode(''); setNewTechPass('');
                            }} variant="secondary" className="w-full py-2">Hinzufügen</Button>
                        </div>
                    </div>
                </div>

                <div className="pt-6 mt-6 border-t flex justify-end">
                    <Button variant="outline" onClick={() => setShowSettings(false)}>Schließen</Button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
}

