          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-20 relative font-sans">
      <div className="sticky top-0 z-20 bg-white shadow-sm border-b px-4 py-3 flex items-center justify-between">
